const input = $input.first().json;
const config = input.config || input;
const now = new Date();
const stamp = now.toISOString().replace(/[-:]/g, '').replace(/.d{3}Z$/, 'Z').replace('T', '-');
const random = Math.random().toString(36).slice(2, 8);
const runId = `n8n-${stamp}-${random}`;
return [{
  json: {
    config,
    run_id: runId,
    worker_request: {
      profile_ids: config.profile_ids,
      max_pages_override: config.max_pages_override,
      max_filter_items_override: config.max_filter_items_override,
      max_enrich_items_override: config.max_enrich_items_override,
      pipeline_run_id: runId
    }
  }
}];

const worker = $input.first().json;
const context = $('Generate Run ID').first().json;
const stats = worker.persistence_stats || {};
const workerFailed = Boolean(worker.error) || worker.status === 'failed';
const persistenceFailed = !worker.persistence_stats || stats.status === 'failed' || stats.failed_count > 0 && stats.persisted_count === 0;
const ok = !workerFailed && !persistenceFailed;
const warnings = [];
if (worker.status === 'completed_with_errors') warnings.push('Worker completed with errors');
if (stats.status === 'completed_with_errors' || (stats.failed_count || 0) > 0) warnings.push('Persistence completed with errors');
return [{
  json: {
    ok,
    run_id: worker.pipeline_run_id || context.run_id,
    config: context.config,
    worker,
    persistence_stats: stats,
    warnings,
    failure_stage: workerFailed ? 'worker_pipeline' : (persistenceFailed ? 'orchestrator_persistence' : null),
    safe_error: worker.error?.message || worker.errors?.[0]?.message || null
  }
}];

function nodeItems(name) {
  try { return $(name).all().map(item => item.json); } catch (error) {}
  try { return $items(name).map(item => item.json); } catch (error) {}
  return [];
}
function firstNode(name) { return nodeItems(name)[0] || {}; }
function compact(values, limit = 8) {
  return [...new Set((values || []).filter(Boolean).map(String))].slice(0, limit);
}
function join(values, limit = 8) { return compact(values, limit).join(', '); }
function formatDate(value) {
  if (!value) return '';
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return String(value).slice(0, 10);
  return date.toLocaleDateString('ru-RU', { timeZone: 'Europe/Samara' });
}
function externalIdFromUrl(url) {
  const match = String(url || '').match(/\/vacancy\/(\d+)/);
  return match ? match[1] : null;
}
function riskLabel(code) {
  const map = {
    salary_low_strong: 'Низкая зарплата',
    salary_low_moderate: 'Зарплата ниже желаемой',
    responsibility_stretch: 'Повышенный уровень ответственности',
    english_required: 'Требуется английский',
    office_outside_samara: 'Обязательный офис вне Самары',
    relocation_required: 'Требуется релокация',
    travel_required: 'Командировки'
  };
  return map[code] || code;
}
function typeLabel(analysis) {
  const semantic = analysis.semantic_snapshot || {};
  const features = analysis.deterministic_features || {};
  const track = semantic.target_track || '';
  const nature = semantic.role_nature || '';
  if (track === 'ai') return 'AI';
  if (track === 'python') return 'Python';
  if (track === 'alt_qa' || nature === 'qa') return 'QA';
  if (track === 'alt_analytics' || nature === 'analytics') return 'Analytics';
  if (features.automation_signal || nature === 'automation') return 'Automation';
  if (track === 'alt_technical' || nature === 'technical_support') return 'Technical';
  return analysis.priority || '';
}
function workFormat(features) {
  if (!features) return 'Не указано';
  if (features.work_format === 'remote') return 'Удалённо';
  if (features.work_format === 'hybrid') return 'Гибрид';
  if (features.work_format === 'office') return 'Офис';
  return 'Не указано';
}
function stackText(analysis) {
  const features = analysis.deterministic_features || {};
  const skills = compact([...(features.matching_skills || []), ...(features.detected_skills || [])], 8);
  return skills.join(', ').slice(0, 180);
}
const run = firstNode('Get Current Run');
const check = firstNode('Build Run Context');
const sheetRows = $input.all().map(item => item.json || {});
const syncPriorities = new Set(check.config?.crm_sync_priorities || ['P1', 'P2', 'ALT']);
const existingByKey = new Map();
const existingByUrlExternalId = new Map();
let maxNumber = 0;
for (const row of sheetRows) {
  const number = Number(row['№'] || row['No'] || 0);
  if (Number.isFinite(number) && number > maxNumber) maxNumber = number;
  const key = String(row['CRM Key'] || '').trim();
  if (key) existingByKey.set(key, row);
  const urlExternalId = externalIdFromUrl(row['Ссылка']);
  if (urlExternalId) existingByUrlExternalId.set(`hh:${urlExternalId}`, row);
}
let nextNumber = maxNumber + 1;
const rows = [];
for (const analysis of run.analyses || []) {
  if (!syncPriorities.has(analysis.priority)) continue;
  const vacancy = analysis.vacancy_snapshot || {};
  const key = `${vacancy.source || 'hh'}:${vacancy.external_id || ''}`;
  const existingByCrmKey = existingByKey.get(key);
  const existingByUrl = existingByUrlExternalId.get(key);
  const existing = existingByCrmKey || existingByUrl || null;
  const semantic = analysis.semantic_snapshot || {};
  const features = analysis.deterministic_features || {};
  const risks = (analysis.risks || []).map(riskLabel);
  const blockers = (analysis.hard_blockers || []).map(riskLabel);
  const rowNumber = existing ? (existing['№'] || existing['No'] || '') : nextNumber++;
  const date = existing && existing['Дата'] ? existing['Дата'] : formatDate(vacancy.collected_at || analysis.created_at);
  const crmRow = {
    '№': rowNumber,
    'Компания': vacancy.company || '',
    'Должность': vacancy.title || '',
    'Тип': typeLabel(analysis),
    'Приоритет': analysis.priority || '',
    'ЗП': vacancy.salary_text || '',
    'Формат': workFormat(features),
    'Стек': stackText(analysis),
    'Дата': date,
    'Ссылка': vacancy.url || '',
    'Score': analysis.final_score ?? '',
    'AI причина': semantic.short_reason || analysis.summary || '',
    'Риски': join(risks, 6),
    'Hard blockers': join(blockers, 6),
    'CRM Key': key,
    'Run ID': analysis.run_id || run.run_id,
    'Анализ обновлён': analysis.created_at || '',
    crm_key: key,
    match_strategy: existingByCrmKey ? 'crm_key' : (existingByUrl ? 'legacy_url' : 'new'),
    crm_action: existing ? 'updated' : 'new'
  };
  rows.push(crmRow);
}
return rows.map(row => ({ json: row }));

function nodeItems(name) {
  try { return $(name).all().map(item => item.json); } catch (error) {}
  try { return $items(name).map(item => item.json); } catch (error) {}
  return [];
}
function firstNode(name) { return nodeItems(name)[0] || {}; }
function escapeHtml(value) {
  return String(value || '').replace(/[&<>"']/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
}
const check = firstNode('Build Run Context');
const run = firstNode('Get Current Run');
const worker = check.worker || {};
const crmRows = nodeItems('Prepare CRM Rows');
const priorityCounts = { P1: 0, P2: 0, P3: 0, ALT: 0 };
for (const analysis of run.analyses || []) {
  if (analysis.priority in priorityCounts) priorityCounts[analysis.priority] += 1;
}
const crmStats = {
  crm_new_count: crmRows.filter(row => row.crm_action === 'new').length,
  crm_updated_count: crmRows.filter(row => row.crm_action === 'updated').length,
  crm_failed_count: 0,
  crm_skipped_count: (run.analyses || []).filter(a => a.priority === 'P3').length
};
const warnings = [...(check.warnings || [])];
const subjectPrefix = check.mode === 'existing_run_replay' ? 'AI Job Automation — повторная CRM/email синхронизация' : 'AI Job Automation — поиск завершён';
const subject = warnings.length
  ? `${subjectPrefix} с предупреждениями — ${new Date().toLocaleDateString('ru-RU')}`
  : `${subjectPrefix} — ${new Date().toLocaleDateString('ru-RU')}`;
const sortedTop = crmRows
  .filter(row => ['P1', 'P2', 'ALT'].includes(row['Приоритет']))
  .sort((a, b) => {
    const order = { P1: 0, P2: 1, ALT: 2 };
    return (order[a['Приоритет']] - order[b['Приоритет']]) || (Number(b.Score || 0) - Number(a.Score || 0));
  })
  .slice(0, check.config?.top_vacancy_limit || 10);
const topHtml = sortedTop.map(row => `
  <li>
    <b>[${escapeHtml(row['Приоритет'])}] ${escapeHtml(row.Score)} — ${escapeHtml(row['Должность'])}</b><br>
    ${escapeHtml(row['Компания'])}<br>
    Причина: ${escapeHtml(row['AI причина'])}<br>
    Риски: ${escapeHtml(row['Риски'] || 'нет')}<br>
    <a href="${escapeHtml(row['Ссылка'])}">Ссылка</a>
  </li>`).join('');
const stats = worker.persistence_stats || check.persistence_stats || {};
const html = `
<p>Поиск вакансий завершён.</p>
<p><b>Run:</b> ${escapeHtml(check.run_id)}</p>
${check.mode === 'existing_run_replay' ? '<p><b>Mode:</b> повторная CRM/email синхронизация по существующему run_id</p>' : ''}
${warnings.length ? `<p><b>Warnings:</b> ${escapeHtml(warnings.join('; '))}</p>` : ''}
<ul>
  <li>Найдено collection: ${escapeHtml(worker.collection_stats?.unique_vacancy_count ?? worker.collection_stats?.raw_vacancy_count ?? '')}</li>
  <li>После preliminary filter: ${escapeHtml(worker.filter_stats?.processed_count ?? '')}</li>
  <li>Полностью проанализировано: ${escapeHtml(worker.enrichment_stats?.enriched_count ?? '')}</li>
  <li>Сохранено в DB: ${escapeHtml(stats.persisted_count ?? '')}</li>
  <li>P1: ${priorityCounts.P1}, P2: ${priorityCounts.P2}, ALT: ${priorityCounts.ALT}, P3: ${priorityCounts.P3}</li>
  <li>CRM новых строк: ${crmStats.crm_new_count}, обновлено: ${crmStats.crm_updated_count}, ошибок: ${crmStats.crm_failed_count}</li>
  <li>Время выполнения Worker: ${escapeHtml(worker.duration_ms ?? '')} ms</li>
</ul>
${check.config?.spreadsheet_url ? `<p><a href="${escapeHtml(check.config.spreadsheet_url)}">Открыть CRM</a></p>` : ''}
<h3>Top vacancies</h3>
<ol>${topHtml}</ol>`;
return [{ json: { to: check.config?.email_to, subject, html, text: html.replace(/<[^>]*>/g, ' '), run_id: check.run_id, crm_stats: crmStats } }];

const check = $input.first().json;
const subject = `AI Job Automation — ошибка поиска — ${new Date().toLocaleDateString('ru-RU')}`;
const html = `<p>Pipeline failed.</p><ul><li>Run: ${check.run_id}</li><li>Stage: ${check.failure_stage || 'unknown'}</li><li>Error: ${check.safe_error || 'see n8n/Worker logs'}</li></ul><p>DB remains source of truth for successfully persisted earlier runs.</p>`;
return [{ json: { to: check.config?.email_to, subject, html, text: html.replace(/<[^>]*>/g, ' '), run_id: check.run_id } }];

function firstNode(name) {
  try { return $(name).first().json || {}; } catch (error) { return { error: { message: `Missing output from ${name}` } }; }
}
function hasError(data) {
  return Boolean(data?.error);
}
function errorText(data) {
  return String(data?.error?.message || data?.message || 'unavailable');
}
const config = $('Config').first().json;
const orchestrator = firstNode('Preflight Orchestrator');
const worker = firstNode('Preflight Worker');
const ollama = firstNode('Preflight Ollama');
const hhAuth = firstNode('Preflight HH Auth');
const hhSession = firstNode('Preflight HH Session');
const failures = [];

if (hasError(orchestrator)) {
  failures.push({ component: 'Orchestrator', reason: 'unavailable', detail: errorText(orchestrator) });
} else if (orchestrator.status !== 'ok') {
  failures.push({ component: 'Orchestrator', reason: 'unhealthy status', detail: `status=${orchestrator.status || 'missing'}` });
}

if (hasError(worker)) {
  failures.push({ component: 'Worker API', reason: 'unavailable', detail: errorText(worker) });
} else if (worker.status !== 'ok' || worker.component !== 'worker') {
  failures.push({ component: 'Worker API', reason: 'unhealthy response', detail: `status=${worker.status || 'missing'} component=${worker.component || 'missing'}` });
}

if (hasError(ollama)) {
  failures.push({ component: 'Ollama', reason: 'unavailable', detail: errorText(ollama) });
} else if (ollama.status !== 'ok' || ollama.component !== 'ollama' || ollama.model_available !== true) {
  failures.push({ component: 'Ollama', reason: 'unhealthy', detail: `status=${ollama.status || 'missing'} model_available=${ollama.model_available}` });
}

if (hasError(hhAuth)) {
  failures.push({ component: 'HH auth', reason: 'unavailable', detail: errorText(hhAuth) });
} else if (hhAuth.status !== 'configured' || hhAuth.component !== 'hh_auth' || hhAuth.storage_state_available !== true) {
  failures.push({ component: 'HH auth', reason: 'storage state not configured', detail: `status=${hhAuth.status || 'missing'} storage_state_available=${hhAuth.storage_state_available}` });
}

if (hasError(hhSession)) {
  failures.push({ component: 'HH session', reason: 'not confirmed', detail: errorText(hhSession) });
} else if (hhSession.status !== 'succeeded' || hhSession.authenticated !== true || hhSession.resume_context_confirmed !== true) {
  failures.push({ component: 'HH session', reason: 'authentication or resume context not confirmed', detail: `status=${hhSession.status || 'missing'} authenticated=${hhSession.authenticated} resume_context_confirmed=${hhSession.resume_context_confirmed}` });
}

const ok = failures.length === 0;
const firstFailure = failures[0] || null;
return [{
  json: {
    ok,
    config,
    failure_stage: ok ? null : 'preflight',
    safe_error: ok ? null : `Preflight failed: ${firstFailure.component} ${firstFailure.reason}`,
    preflight: {
      orchestrator: { status: orchestrator.status || null },
      worker: { status: worker.status || null, component: worker.component || null },
      ollama: { status: ollama.status || null, component: ollama.component || null, model_available: ollama.model_available === true },
      hh_auth: { status: hhAuth.status || null, component: hhAuth.component || null, storage_state_available: hhAuth.storage_state_available === true },
      hh_session: { status: hhSession.status || null, authenticated: hhSession.authenticated === true, resume_context_confirmed: hhSession.resume_context_confirmed === true }
    },
    failures
  }
}];

const input = $input.first().json;
const config = input.config || input;
const existingRunId = String(input.existing_run_id || config.existing_run_id || '').trim();
const runId = String(input.run_id || existingRunId || '').trim();
if (!runId) {
  throw new Error('run_id is required for CRM/email sync');
}
const replayMode = Boolean(existingRunId) && !input.worker;
const warnings = [...(input.warnings || [])];
return [{
  json: {
    ok: input.ok !== false,
    run_id: runId,
    config,
    worker: input.worker || { status: 'existing_run_replay' },
    persistence_stats: input.persistence_stats || {},
    warnings,
    failure_stage: input.failure_stage || null,
    safe_error: input.safe_error || null,
    mode: replayMode ? 'existing_run_replay' : 'worker_pipeline'
  }
}];
